--- build.py ---
import os, re, html, json, urllib.parse

SITE = "site"
files = [f for f in sorted(os.listdir(SITE)) if f.lower().endswith(".html")]
redirects = {}
for f in files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    m = re.search(r'<meta\s+http-equiv="refresh"\s+content="0;\s*url=([^"]+)"', raw, re.I)
    if m:
        redirects[f] = m.group(1)

NONWORD = {"index.html", "sobre.html", "contato.html"}
word_files = [f for f in files if f not in redirects and f not in NONWORD]

def canon(f):
    seen = set()
    while f in redirects and f not in seen:
        seen.add(f); f = redirects[f]
    return f

word_of = {}
for f in word_files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    w = html.unescape(re.search(r'<h1>(.*?)</h1>', raw, re.S).group(1)).strip()
    word_of[f] = w
assert len(word_of) == len(set(w.lower() for w in word_of.values()))

ALIASES = {}
for stub, target in redirects.items():
    tf = canon(target)
    if tf in word_of:
        ALIASES[stub[:-5].lower()] = word_of[tf]

def resolve_target(fname):
    if not fname.lower().endswith(".html"):
        return None
    tf = canon(fname)
    return word_of.get(tf)

def extract_links(fname, section_id, raw):
    sec = re.search(r'<section id="%s">(.*?)</section>' % re.escape(section_id), raw, re.S)
    if not sec:
        return []
    out = []
    for m in re.finditer(r'<a\s+href="([^"]+\.html)"[^>]*>(.*?)</a>', sec.group(1)):
        w = resolve_target(urllib.parse.unquote(m.group(1)))
        if w:
            out.append(w)
    return out

OUT = {}
THEME = {}
order = []
for f in word_files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    w = word_of[f]
    m = re.search(r'<p class="tema">Tema:\s*(.*?)</p>', raw)
    THEME[w] = html.unescape(m.group(1)).strip() if m else ""
    if w not in OUT:
        OUT[w] = {}
        order.append(w)
    for kind, sec in (("s", "sinonimos"), ("a", "analogas")):
        for t in extract_links(f, sec, raw):
            if t != w:
                OUT[w].setdefault(t, set()).add(kind)

# undirected distinct pairs (accent-preserving lowercase key)
pairs = set()
degree = {w.lower(): 0 for w in OUT}
for w, adj in OUT.items():
    for t in adj:
        a, b = w.lower(), t.lower()
        if a == b:
            continue
        key = (a, b) if a < b else (b, a)
        if key not in pairs:
            pairs.add(key)
            degree[a] += 1
            degree[b] += 1

deg_canon = {w: degree[w.lower()] for w in OUT}
most_word = sorted(deg_canon.items(), key=lambda kv: (-kv[1], kv[0][0].lower()))[0][0]

words_json = {w: sorted(OUT[w].keys()) for w in order}
open("words.json", "w", encoding="utf-8").write(
    json.dumps(words_json, ensure_ascii=False, indent=2) + "\n")

result = {"words": len(order), "relations": len(pairs), "most_connected": most_word}
open("result.json", "w", encoding="utf-8").write(json.dumps(result, ensure_ascii=False, indent=2) + "\n")

# embed into template
data = {
    "words": [[w, THEME[w]] for w in order],
    "out": {w: [[t, "".join(sorted(kinds))] for t, kinds in OUT[w].items()] for w in order},
    "alias": ALIASES,
    "stats": {"words": len(order), "relations": len(pairs), "most": [most_word, deg_canon[most_word]]},
}
tpl = open("universe/_tpl.html", encoding="utf-8").read()
out_html = tpl.replace("__DATA__", json.dumps(data, ensure_ascii=False))
assert "__DATA__" not in out_html
os.makedirs("universe", exist_ok=True)
open("universe/index.html", "w", encoding="utf-8").write(out_html)

print("words:", len(order))
print("relations:", len(pairs))
print("most_connected:", most_word, deg_canon[most_word])
print("top10:", sorted(deg_canon.items(), key=lambda kv: (-kv[1], kv[0].lower()))[:10])
print("themes:", sorted(THEME.values()))
print("alias:", ALIASES)
print("out total links:", sum(len(v) for v in OUT.values()))
print("saudade out:", words_json["saudade"])
print("palavra degree:", deg_canon["palavra"], "tempo degree:", deg_canon["tempo"])


