import os, re, html, urllib.parse, json, collections

SITE = "site"
files = sorted(os.listdir(SITE))
files = [f for f in files if f.lower().endswith(".html")]
print("total html files:", len(files))

# detect redirect stubs
redirects = {}
for f in files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    m = re.search(r'<meta\s+http-equiv="refresh"\s+content="0;\s*url=([^"]+)"', raw, re.I)
    if m:
        redirects[f] = m.group(1)
print("redirect stubs:", redirects)

# all href targets
targets = set()
for f in files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    for m in re.finditer(r'href="([^"#]+\.html)"', raw):
        targets.add(urllib.parse.unquote(m.group(1)))
missing = sorted(t for t in targets if t not in files)
print("missing link targets:", missing)

# h1 words
words = {}
dup = []
for f in files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    if f in redirects:
        continue
    m = re.search(r'<h1>(.*?)</h1>', raw, re.S)
    if not m:
        print("NO H1:", f)
        continue
    w = html.unescape(m.group(1)).strip()
    key = w.casefold()
    if key in words:
        dup.append((key, words[key], f))
    words[key] = f
print("distinct h1 words:", len(words))
print("dups:", dup)

# non-word pages (no h1 / no tema)
print("files without h1:", [f for f in files if f not in redirects and not re.search(r'<h1>', open(os.path.join(SITE, f), encoding="utf-8").read())])

# section types
secs = collections.Counter()
for f in files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    for m in re.finditer(r'<section id="([^"]+)"', raw):
        secs[m.group(1)] += 1
print("section ids:", dict(secs))

# temas
temas = collections.Counter()
for f in files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    m = re.search(r'<p class="tema">Tema:\s*(.*?)</p>', raw)
    if m:
        temas[m.group(1).strip()] += 1
    elif f not in redirects and f not in ("index.html", "sobre.html", "contato.html"):
        print("NO TEMA:", f)
print("temas:", dict(temas))

# check a large file
print("\n--- tempo.html ---")
print(open(os.path.join(SITE, "tempo.html"), encoding="utf-8").read())
print("\n--- heranca.html ---")
print(open(os.path.join(SITE, "heranca.html"), encoding="utf-8").read())


