import os, re, html, urllib.parse, unicodedata

SITE = "site"
files = [f for f in sorted(os.listdir(SITE)) if f.lower().endswith(".html")]
redirects = {}
for f in files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    m = re.search(r'<meta\s+http-equiv="refresh"\s+content="0;\s*url=([^"]+)"', raw, re.I)
    if m:
        redirects[f] = m.group(1)

ghosts = {'em-construcao.html', 'link-antigo.html', 'pagina-removida.html', 'rascunho-3.html', 'xpto-2.html'}
word_files = [f for f in files if f not in redirects and f not in ("index.html", "sobre.html", "contato.html")]

def canon_file(f):
    while f in redirects:
        f = redirects[f]
    return f

# who links to ghosts, with anchor text
print("--- ghost link usage ---")
for f in word_files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    for m in re.finditer(r'<li><a href="([^"]+)">(.*?)</a></li>', raw):
        t = urllib.parse.unquote(m.group(1))
        if t in ghosts:
            print(f, "->", t, "| text:", html.unescape(m.group(2)).strip())

# self links
print("--- self links ---")
for f in word_files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    for m in re.finditer(r'<a href="([^"]+\.html)"', raw):
        t = urllib.parse.unquote(m.group(1))
        if t == f:
            print(f, "self-ref (in nav/footer/sections)")

# h1 vs stem
print("--- h1 vs stem differences ---")
def norm(s):
    return unicodedata.normalize("NFD", s.casefold()).encode("ascii", "ignore").decode()
diffs = 0
for f in word_files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    w = html.unescape(re.search(r'<h1>(.*?)</h1>', raw, re.S).group(1)).strip()
    stem = f[:-5]
    if norm(w) != norm(stem):
        diffs += 1
        print(f"{f!r:30} h1={w!r}")
print("h1/stem mismatches:", diffs)

# count links per section
tot_syn = tot_ana = 0
for f in word_files:
    raw = open(os.path.join(SITE, f), encoding="utf-8").read()
    syn = re.search(r'<section id="sinonimos">.*?</section>', raw, re.S).group(0)
    ana = re.search(r'<section id="analogas">.*?</section>', raw, re.S).group(0)
    tot_syn += len(re.findall(r'<a ', syn))
    tot_ana += len(re.findall(r'<a ', ana))
print("total synonym links:", tot_syn, "analog links:", tot_ana)


